// Counts this run's results by status.
// The loop's done output holds every row saved by 'Save Result' across all batches.
const rows = $input.all().map(i => i.json);
const counts = {};
for (const r of rows) counts[r.status] = (counts[r.status] || 0) + 1;
return [{ json: { checked: rows.length, ...counts,
  uk_boards: rows.filter(r => r.status === 'uk').map(r => r.source + ':' + r.slug + ' (' + r.uk_jobs + ')').slice(0, 50) } }];

// Calls each company's public job board feed and counts open jobs and UK jobs.
// Runs inside the Code node so only the summary is kept, not every job description.
const sleep = ms => new Promise(r => setTimeout(r, ms));

const UK_WORDS = /\b(united kingdom|uk|u\.k\.|england|scotland|wales|northern ireland|great britain|britain)\b/i;
const UK_CITIES = /\b(london|manchester|edinburgh|glasgow|leeds|sheffield|liverpool|newcastle upon tyne|nottingham|brighton|bristol|cardiff|belfast|aberdeen|milton keynes|southampton|leicester|coventry|bath|exeter|oxford|cambridge|birmingham|reading)\b/i;
const NOT_UK = /\b(usa|united states|canada|australia|ontario|massachusetts|alabama|new hampshire)\b|,\s*(?!UK\b|GB\b)[A-Z]{2}\b/;

const isUkText = s => {
  if (!s) return false;
  if (UK_WORDS.test(s)) return true;
  return UK_CITIES.test(s) && !NOT_UK.test(s);
};

const this_helpers = this.helpers;
async function get(url) {
  const res = await this_helpers.httpRequest({
    method: 'GET', url, json: true, returnFullResponse: true,
    ignoreHttpStatusErrors: true, timeout: 20000
  });
  return res;
}

const out = [];
for (const item of $input.all()) {
  const { source, slug } = item.json;
  const row = { source, slug, status: 'error', open_jobs: null, uk_jobs: null, company_name: null,
                last_checked_at: new Date().toISOString() };
  try {
    let url;
    if (source === 'greenhouse') url = 'https://boards-api.greenhouse.io/v1/boards/' + encodeURIComponent(slug) + '/jobs';
    else if (source === 'ashby') url = 'https://api.ashbyhq.com/posting-api/job-board/' + encodeURIComponent(slug);
    else if (source === 'workable') url = 'https://apply.workable.com/api/v1/widget/accounts/' + encodeURIComponent(slug);
    else throw new Error('unknown source ' + source);

    const res = await get(url);
    if (res.statusCode === 404) { row.status = 'not_found'; }
    else if (res.statusCode !== 200) { row.status = 'error'; row.company_name = 'HTTP ' + res.statusCode; }
    else {
      const body = res.body || {};
      const jobs = Array.isArray(body.jobs) ? body.jobs : [];
      let uk = 0;
      for (const j of jobs) {
        let hit = false;
        if (source === 'greenhouse') {
          hit = isUkText(j.location && j.location.name);
        } else if (source === 'ashby') {
          if (j.isListed === false) continue;
          const country = j.address && j.address.postalAddress && j.address.postalAddress.addressCountry;
          hit = isUkText(country) || isUkText(j.location) ||
                (j.secondaryLocations || []).some(s => isUkText(s.location) ||
                  isUkText(s.address && s.address.addressCountry));
        } else if (source === 'workable') {
          const locs = (j.locations || []).concat([{ country: j.country, countryCode: j.countryCode, city: j.city }]);
          hit = locs.some(l => l && (l.countryCode === 'GB' || isUkText(l.country)));
        }
        if (hit) uk++;
      }
      row.open_jobs = source === 'ashby' ? jobs.filter(j => j.isListed !== false).length : jobs.length;
      row.uk_jobs = uk;
      row.status = row.open_jobs === 0 ? 'no_jobs' : (uk > 0 ? 'uk' : 'no_uk');

      if (source === 'workable') row.company_name = body.name || null;
      if (source === 'greenhouse' && uk > 0) {
        await sleep(300);
        const b = await get('https://boards-api.greenhouse.io/v1/boards/' + encodeURIComponent(slug));
        if (b.statusCode === 200 && b.body) row.company_name = b.body.name || null;
      }
    }
  } catch (e) {
    row.status = 'error';
    row.company_name = String(e.message || e).slice(0, 200);
  }
  out.push({ json: row });
  await sleep(400); // polite pace: about 1-2 requests a second
}
return out;
